              "\u0415\u0441\u043B\u0438 \u0437\u0430\u0433\u0430\u0434\u0430\u043D\u043E kot, \u0430 \u0432\u044B \u0432\u0432\u0435\u043B\u0438 sok, \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0431\u0443\u0434\u0435\u0442 1 \u0438\u0437 3: \u0441\u043E\u0432\u043F\u0430\u043B\u0430 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0440\u0435\u0434\u043D\u044F\u044F \u0431\u0443\u043A\u0432\u0430. K \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u0432 \u0441\u043B\u043E\u0432\u0435 kot \u043E\u043D\u0430 \u043F\u0435\u0440\u0432\u0430\u044F, \u0430 \u0432 sok \u2014 \u0442\u0440\u0435\u0442\u044C\u044F. \u0421\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044F \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0438 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u043F\u044B\u0442\u043E\u043A, \u0432\u044B \u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u043E \u0441\u0443\u0436\u0430\u0435\u0442\u0435 \u043A\u0440\u0443\u0433 \u043F\u043E\u0438\u0441\u043A\u0430."),
            rule_section(:variants, "\u0418\u0433\u0440\u0430\u0439\u0442\u0435 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E \u0438\u043B\u0438 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C\u0438",
              "\u0415\u0441\u043B\u0438 \u0432\u044B \u0445\u043E\u0437\u044F\u0438\u043D \u0441\u0442\u043E\u043B\u0430, \u0442\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0440\u0435\u0436\u0438\u043C \u0438\u0433\u0440\u044B. \u0414\u043B\u044F \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u044B \u0435\u0441\u0442\u044C \u0434\u0432\u0430 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430:",
              "- Daily Krowa \u2014 \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u043A\u0430\u0436\u0434\u044B\u0439 \u0434\u0435\u043D\u044C, \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u0435 \u0434\u043B\u044F \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "- \u00AB\u0421\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E\u00BB \u2014 \u0438\u0433\u0440\u0430 \u0441\u043E \u0441\u043B\u043E\u0432\u0430\u043C\u0438 \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u043C\u043E\u0439 \u0434\u043B\u0438\u043D\u044B.",
              "\u0418\u0433\u0440\u0430\u0442\u044C \u0441 \u0434\u0440\u0443\u0433\u0438\u043C\u0438 \u0442\u043E\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u0434\u0432\u0443\u043C\u044F \u0441\u043F\u043E\u0441\u043E\u0431\u0430\u043C\u0438:",
              "- \u00AB\u0413\u043E\u043D\u043A\u0430\u00BB \u2014 \u0441\u043E\u0440\u0435\u0432\u043D\u043E\u0432\u0430\u043D\u0438\u0435, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0432\u0441\u0435 \u0443\u0433\u0430\u0434\u044B\u0432\u0430\u044E\u0442 \u043E\u0434\u043D\u043E \u0438 \u0442\u043E \u0436\u0435 \u0441\u043B\u043E\u0432\u043E. \u0412 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u0438 \u043E\u0442 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u043E\u043C\u0443 \u043F\u043E\u043D\u0430\u0434\u043E\u0431\u0438\u043B\u043E\u0441\u044C \u043C\u0435\u043D\u044C\u0448\u0435 \u043F\u043E\u043F\u044B\u0442\u043E\u043A, \u0438\u043B\u0438 \u0442\u043E\u0442, \u043A\u0442\u043E \u0443\u0433\u0430\u0434\u0430\u043B \u0431\u044B\u0441\u0442\u0440\u0435\u0435.",
              "- \u00AB\u0411\u0430\u0448\u043D\u044F \u0441\u043B\u043E\u0432\u00BB \u2014 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u043D\u0430\u044F \u0438\u0433\u0440\u0430. \u0417\u0434\u0435\u0441\u044C \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430, \u0430 \u0432\u0441\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438 \u0432\u0432\u043E\u0434\u044F\u0442 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u0438 \u0432\u0438\u0434\u044F\u0442, \u0447\u0442\u043E \u0432\u0432\u043E\u0434\u0438\u043B\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435.",
              "Daily Krowa \u0437\u0430\u043A\u0440\u044B\u0442\u0430 \u043E\u0442 \u043F\u043E\u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0438\u0445: \u043A \u043D\u0435\u0439 \u043D\u0435\u043B\u044C\u0437\u044F \u043F\u0440\u0438\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u044C\u0441\u044F \u0438\u043B\u0438 \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0437\u0430 \u043D\u0435\u0439. \u0418\u043D\u0430\u0447\u0435 \u0432\u0435\u0434\u044C \u043F\u043E\u0442\u043E\u043C \u0431\u044B\u043B\u043E \u0431\u044B \u0441\u043B\u0438\u0448\u043A\u043E\u043C \u043B\u0435\u0433\u043A\u043E \u0443\u0433\u0430\u0434\u0430\u0442\u044C!",
              "\u0417\u0430 \u0432\u0441\u0435\u043C\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u043C\u0438 \u0440\u0435\u0436\u0438\u043C\u0430\u043C\u0438 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C, \u0435\u0441\u043B\u0438 \u0441\u0442\u043E\u043B \u043E\u0442\u043A\u0440\u044B\u0442. \u041F\u0440\u0438\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0432\u0448\u0438\u0441\u044C \u043A \u00AB\u041A\u0440\u043E\u0432\u0435\u00BB, \u043F\u043E\u043A\u0430 \u043A\u0442\u043E-\u0442\u043E \u0443\u0433\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u0432\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u0443\u0437\u043D\u0430\u0442\u044C \u0435\u0433\u043E \u0434\u043B\u0438\u043D\u0443, \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u0438 \u0438\u0445 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E. \u041C\u043E\u0436\u043D\u043E \u0434\u0430\u0436\u0435 \u043D\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u0432 \u0447\u0430\u0442\u0435: \u00ABp \u043D\u0430 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043E\u043C \u043C\u0435\u0441\u0442\u0435! \u0421\u0435\u0440\u044C\u0451\u0437\u043D\u043E, \u0442\u0430\u043C \u0431\u0443\u0434\u0435\u0442 p!\u00BB \u041D\u043E \u044F \u043D\u0435 \u0441\u043E\u0432\u0435\u0442\u0443\u044E."),
            rule_section(:vocabulary, "\u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0432\u043E\u0438\u0445 \u0441\u043B\u043E\u0432",
              "\u0412 \u0440\u0435\u0436\u0438\u043C\u0435 \u00AB\u0421\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E\u00BB \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043E\u0434\u043D\u0430 \u0441\u0443\u043F\u0435\u0440\u0441\u043F\u043E\u0441\u043E\u0431\u043D\u043E\u0441\u0442\u044C. \u041C\u043E\u0436\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u0441\u043B\u043E\u0432\u0430 \u0432 \u0441\u043B\u043E\u0432\u0430\u0440\u044C, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0445\u0440\u0430\u043D\u0438\u0442 \u0432\u0430\u0448\u0438 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E. \u0425\u043C... \u0435\u0441\u043B\u0438 \u043D\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u0442\u0443\u0434\u0430 asdfasdfasdf, \u044D\u0442\u043E \u0442\u043E\u0436\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F, \u043D\u043E \u044F \u0432\u0441\u0451-\u0442\u0430\u043A\u0438 \u043D\u0430\u0434\u0435\u044E\u0441\u044C, \u0447\u0442\u043E \u0443\u0434\u043E\u0432\u043E\u043B\u044C\u0441\u0442\u0432\u0438\u0435 \u043E\u0442 \u0438\u0433\u0440\u044B \u0432\u0430\u0436\u043D\u0435\u0435 \u043D\u0430\u043A\u0440\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u044F \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0432 \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0430\u0445.",
              "\u0422\u0430\u043A \u0447\u0442\u043E, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0432\u0432\u043E\u0434\u0438\u0442\u044C smerfy \u0432 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0438, \u043F\u0440\u043E\u0441\u0442\u043E \u0432\u043E\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435\u0441\u044C \u043A\u043D\u043E\u043F\u043A\u043E\u0439 \u00AB\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0432 \u0441\u043B\u043E\u0432\u0430\u0440\u044C \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C\u00BB. \u041D\u043E \u0432 Daily Krowa \u0438 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u043D\u044B\u0445 \u0440\u0435\u0436\u0438\u043C\u0430\u0445 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u044D\u0442\u043E \u0441\u043B\u043E\u0432\u043E \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0441\u044F. \u0418 \u043D\u0435 \u043F\u043E\u0442\u043E\u043C\u0443, \u0447\u0442\u043E \u044F \u043D\u0435 \u043B\u044E\u0431\u043B\u044E \u0441\u043C\u0443\u0440\u0444\u0438\u043A\u043E\u0432, \u2014 \u0435\u0433\u043E \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435\u0442 \u0432 \u0431\u0430\u0437\u0435."),
            rule_section(:guessing, "\u041A\u0430\u043A \u0438\u0433\u0440\u0430\u0442\u044C",
              "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041F\u043E\u0441\u043B\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0438 \u043F\u043E\u043B\u0435 \u0432\u0432\u043E\u0434\u0430 \u043E\u0447\u0438\u0449\u0430\u0435\u0442\u0441\u044F. \u041D\u0435\u0432\u0435\u0440\u043D\u0430\u044F \u0434\u043B\u0438\u043D\u0430, \u0441\u043B\u043E\u0432\u043E \u043D\u0435 \u0438\u0437 \u0441\u043B\u043E\u0432\u0430\u0440\u044F, \u043F\u043E\u0432\u0442\u043E\u0440 \u0438\u043B\u0438 \u043E\u0442\u0432\u0435\u0442 \u043D\u0435 \u0432 \u0441\u0432\u043E\u044E \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u043D\u0435 \u0440\u0430\u0441\u0445\u043E\u0434\u0443\u044E\u0442 \u043F\u043E\u043F\u044B\u0442\u043A\u0443, \u0437\u0430\u0442\u043E \u0438\u0437\u0434\u0430\u044E\u0442 \u0437\u0430\u0431\u0430\u0432\u043D\u044B\u0439 \u0437\u0432\u0443\u043A."),
            rule_section(:daily, "Daily Krowa",
              "\u0412 Daily Krowa \u043C\u043E\u0436\u0435\u0442 \u0432\u044B\u043F\u0430\u0441\u0442\u044C \u0441\u043B\u043E\u0432\u043E \u0434\u043B\u0438\u043D\u043E\u0439 \u043E\u0442 \u0442\u0440\u0451\u0445 \u0434\u043E \u0434\u0435\u0432\u044F\u0442\u0438 \u0431\u0443\u043A\u0432. \u041E\u043D\u043E \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u043E \u0441\u0435\u0440\u0432\u0435\u0440\u043D\u043E\u043C\u0443 \u0432\u0440\u0435\u043C\u0435\u043D\u0438, \u0442\u0430\u043A \u0447\u0442\u043E, \u0435\u0441\u043B\u0438 \u0432\u0430\u043C \u043D\u0443\u0436\u043D\u043E \u0434\u0440\u0443\u0433\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u0432\u0437\u043B\u043E\u043C\u0430\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440 \u0438 \u043F\u043E\u043C\u0435\u043D\u044F\u0442\u044C \u0434\u0430\u0442\u0443.",
              "Daily Krowa \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u0438\u043D \u0440\u0430\u0437. \u0415\u0441\u043B\u0438 \u0432\u044B \u0443\u0433\u0430\u0434\u0430\u0435\u0442\u0435 \u0441\u043B\u043E\u0432\u043E, \u0441\u0434\u0430\u0434\u0438\u0442\u0435\u0441\u044C \u0438\u043B\u0438 \u043F\u0440\u0435\u0440\u0432\u0451\u0442\u0435 \u0438\u0433\u0440\u0443, \u0434\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0434\u043D\u044F \u044D\u0442\u043E\u0442 \u0440\u0435\u0436\u0438\u043C \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0434\u043B\u044F \u0432\u0430\u0448\u0435\u0433\u043E \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430."),
            rule_section(:race, "\u0413\u043E\u043D\u043A\u0430",
              "\u0412 \u00AB\u0413\u043E\u043D\u043A\u0435\u00BB \u043A\u0430\u0436\u0434\u044B\u0439 \u0443\u0433\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E. \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u0434\u0430\u0442\u044C \u0434\u043B\u0438\u043D\u0443 \u0441\u043B\u043E\u0432\u0430 \u0438\u043B\u0438 \u0434\u043E\u0432\u0435\u0440\u0438\u0442\u044C\u0441\u044F \u0441\u043B\u0443\u0447\u0430\u044E. \u041F\u0440\u0438 \u043B\u044E\u0431\u043E\u043C \u0432\u044B\u0431\u043E\u0440\u0435 \u0445\u043E\u0437\u044F\u0438\u043D \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u0433\u0430\u0434\u0430\u0442\u044C \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u2014 \u0442\u043E\u0433\u0434\u0430 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u043E\u0431\u043D\u0443\u043B\u044F\u044E\u0442\u0441\u044F. \u0422\u0430\u043A\u0436\u0435 \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0443\u043F\u043E\u043C\u044F\u043D\u0443\u0442\u044B\u0439 \u0432\u044B\u0448\u0435 \u0441\u043F\u043E\u0441\u043E\u0431 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F:",
              "- \u041F\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438: \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u0443 \u043A\u043E\u0433\u043E \u043F\u0440\u043E\u0448\u043B\u043E \u043C\u0435\u043D\u044C\u0448\u0435 \u0432\u0441\u0435\u0433\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u043E\u0442 \u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u043B\u043E\u0432\u0430 \u0434\u043E \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0438 \u0432\u0435\u0440\u043D\u043E\u0433\u043E \u043E\u0442\u0432\u0435\u0442\u0430. \u0412\u0440\u0435\u043C\u044F \u0438\u0437\u043C\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u0447\u0430\u0441\u0430\u043C\u0438, \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u043C\u0438 \u0441 \u0441\u0435\u0440\u0432\u0435\u0440\u043E\u043C.",
              "- \u041F\u043E \u043F\u043E\u043F\u044B\u0442\u043A\u0430\u043C: \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u0443\u0433\u0430\u0434\u0430\u043B \u0441\u043B\u043E\u0432\u043E \u0437\u0430 \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0435\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043F\u0440\u0438\u043D\u044F\u0442\u044B\u0445 \u043F\u043E\u043F\u044B\u0442\u043E\u043A.",
              "\u041F\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u0445 \u043F\u043E\u0431\u0435\u0434\u0430 \u043E\u0431\u0449\u0430\u044F.",
              "\u0415\u0441\u043B\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u043B\u0438 \u0443\u0433\u0430\u0434\u044B\u0432\u0430\u0442\u044C, \u0430 \u0432\u044B \u0443\u0436\u0435 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u0440\u0430\u0432\u043D\u044F\u0442\u044C\u0441\u044F \u0441 \u043B\u0443\u0447\u0448\u0438\u043C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u043C, \u0438\u0433\u0440\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u0432\u0430\u043C \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u0441\u043B\u043E\u0432\u043E."),
            rule_section(:tower, "\u0411\u0430\u0448\u043D\u044F \u0441\u043B\u043E\u0432",
              "\u0412 \u00AB\u0411\u0430\u0448\u043D\u0435\u00BB \u0432\u044B \u0445\u043E\u0434\u0438\u0442\u0435 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438, \u0430 \u043F\u043E\u0441\u043B\u0435 \u0443\u0433\u0430\u0434\u0430\u043D\u043D\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u043D\u043E\u0432\u044B\u0439 \u0440\u0430\u0443\u043D\u0434. \u0414\u043B\u0438\u043D\u0430 \u0441\u043B\u043E\u0432 \u2014 \u043E\u0442 3 \u0434\u043E 8 \u0431\u0443\u043A\u0432. \u041E\u0431\u0449\u0438\u0439 \u0437\u0430\u043F\u0430\u0441 \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0434\u043B\u0438\u043D\u044B:",
              "- 3 \u0431\u0443\u043A\u0432\u044B: 15 \u043F\u043E\u043F\u044B\u0442\u043E\u043A.",
              "- 4 \u0431\u0443\u043A\u0432\u044B: 24 \u043F\u043E\u043F\u044B\u0442\u043A\u0438.",
              "- 5 \u0431\u0443\u043A\u0432: 30 \u043F\u043E\u043F\u044B\u0442\u043E\u043A.",
              "- 6 \u0431\u0443\u043A\u0432: 42 \u043F\u043E\u043F\u044B\u0442\u043A\u0438.",
              "- 7 \u0431\u0443\u043A\u0432: 49 \u043F\u043E\u043F\u044B\u0442\u043E\u043A.",
              "- 8 \u0431\u0443\u043A\u0432: 64 \u043F\u043E\u043F\u044B\u0442\u043A\u0438.",
              "\u00AB\u0411\u0430\u0448\u043D\u044F\u00BB \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u0438\u0441\u0447\u0435\u0440\u043F\u0430\u043D\u044B \u0438\u043B\u0438 \u0445\u043E\u0437\u044F\u0438\u043D \u0441\u0434\u0430\u0451\u0442\u0441\u044F. \u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u2014 \u0447\u0438\u0441\u043B\u043E \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043D\u044B\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432. \u0412 \u0441\u043F\u0438\u0441\u043A\u0435 \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u0432 \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u044B \u0441\u043B\u043E\u0432\u0430 \u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043F\u043E\u043F\u044B\u0442\u043E\u043A."),
            rule_section(:personal, "\u041C\u0443\u0437\u044B\u043A\u0430 \u0438 \u0437\u0432\u0443\u043A\u043E\u0432\u044B\u0435 \u044D\u0444\u0444\u0435\u043A\u0442\u044B",
              "\u041C\u0443\u0437\u044B\u043A\u0430 \u0438 \u044D\u0444\u0444\u0435\u043A\u0442\u044B \u00AB\u041A\u0440\u043E\u0432\u044B\u00BB \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u044B. \u041F\u043E Ctrl+P \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u0438\u0445 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0442\u0435\u043B\u0438 \u0438 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0440\u0435\u0433\u0443\u043B\u0438\u0440\u043E\u0432\u043A\u0430 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u0438. \u041D\u0430 \u044D\u0442\u0438 \u0437\u0432\u0443\u043A\u0438 \u0442\u0430\u043A\u0436\u0435 \u0432\u043B\u0438\u044F\u044E\u0442 \u043E\u0431\u0449\u0435\u0435 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0438\u0433\u0440\u043E\u0432\u044B\u0445 \u0437\u0432\u0443\u043A\u043E\u0432 \u0432 Power Games."),
            rule_section(:results, "\u0413\u0430\u043B\u0435\u0440\u0435\u044F, \u0441\u043B\u043E\u0432\u0430\u0440\u044C \u0438 \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0438",
              "\u0413\u0430\u043B\u0435\u0440\u0435\u044F \u0437\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0441\u043B\u043E\u0432\u0430, \u0443\u0433\u0430\u0434\u0430\u043D\u043D\u044B\u0435 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E, \u0438 \u043B\u0443\u0447\u0448\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E. \u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0435\u0451 \u043C\u043E\u0436\u043D\u043E \u0434\u043E \u043F\u0430\u0440\u0442\u0438\u0438 \u0438 \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0451.",
              "\u0412 \u043C\u0435\u043D\u044E \u0433\u0430\u043B\u0435\u0440\u0435\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u043A\u0430 \u043F\u043E \u0434\u0430\u0442\u0435, \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0443 \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u0438\u043B\u0438 \u0434\u043B\u0438\u043D\u0435 \u0441\u043B\u043E\u0432\u0430. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043B\u043E\u0432\u043E \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0435\u0433\u043E \u0440\u0435\u0439\u0442\u0438\u043D\u0433. \u041F\u043E\u0441\u043B\u0435 \u0438\u0433\u0440\u044B \u043C\u043E\u0436\u043D\u043E \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u0442\u044C\u0441\u044F \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u2014 \u0442\u043E\u0433\u0434\u0430 \u0440\u0435\u0439\u0442\u0438\u043D\u0433 \u044D\u0442\u043E\u0433\u043E \u0441\u043B\u043E\u0432\u0430 \u0442\u043E\u0436\u0435 \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F.",
              "\u041F\u0443\u043D\u043A\u0442 \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u043E\u0432 \u0432 \u0433\u043B\u0430\u0432\u043D\u043E\u043C \u043C\u0435\u043D\u044E \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u043F\u043E \u0441\u043B\u043E\u0432\u0430\u043C \u0438 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u00AB\u0411\u0430\u0448\u043D\u0438 \u0441\u043B\u043E\u0432\u00BB. \u0413\u0430\u043B\u0435\u0440\u0435\u044F \u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0441\u043B\u043E\u0432\u0430\u0440\u044C \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430. \u0427\u0442\u043E\u0431\u044B \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0432\u043E\u0438 \u0441\u043B\u043E\u0432\u0430, \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0441\u043B\u043E\u0432\u0430\u0440\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u00AB\u041A\u0440\u043E\u0432\u044B\u00BB, \u043E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 \u0438\u0445 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u043D\u044B\u0445."),
            rule_section(:saving, "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0438\u0433\u0440\u044B",
